from matplotlib.patches import Rectangle, FancyBboxPatch
fig = plt.gcf(); fig.set_size_inches(6.6, 3.0)
ax = fig.add_axes([0, 0, 1, 1])
s = 0.22
def rod(x, y):
    for k in range(10):
        ax.add_patch(Rectangle((x, y + k * s), s, s, fc='white', ec='black', lw=0.9))
def unit(x, y, ec='black'):
    ax.add_patch(Rectangle((x, y), s, s, fc='white', ec=ec, lw=1.2))
for i in range(4):
    rod(0.2 + i * 0.4, 0.6)
for j in range(5):
    unit(1.9, 0.6 + j * 0.35)
ax.text(1.05, 0.15, '4 tens, 5 ones', ha='center', va='center', fontsize=12)
ax.annotate('', xy=(3.15, 1.7), xytext=(2.45, 1.7), arrowprops=dict(arrowstyle='->', lw=1.5))
for g in range(3):
    x0 = 3.45 + g * 1.55
    ax.add_patch(FancyBboxPatch((x0 - 0.12, 0.5), 1.25, 2.45, boxstyle='round,pad=0.05', fc='white', ec='blue', lw=1.4))
    rod(x0, 0.6)
    for j in range(5):
        unit(x0 + 0.55 + (j % 2) * 0.32, 0.6 + (j // 2) * 0.35)
    ax.text(x0 + 0.5, 0.15, '1 ten, 5 ones', ha='center', va='center', fontsize=10, color='blue')
ax.set_xlim(0, 8.2); ax.set_ylim(-0.1, 3.1); ax.set_aspect('equal'); ax.axis('off')
